diff --git a/mailnews/search/public/nsIMsgFilterList.idl b/mailnews/search/public/nsIMsgFilterList.idl
index fa294d50632..016b751c316 100644
--- a/mailnews/search/public/nsIMsgFilterList.idl
+++ b/mailnews/search/public/nsIMsgFilterList.idl
@@ -104,6 +104,12 @@ interface nsIMsgFilterList : nsISupports {
      * @param filter   Optional filter object that reports the message.
      */
     void logFilterMessage(in AString message, [optional] in nsIMsgFilter filter);
+
+    /**
+     * Returns true if any filters matching `filterType` require the
+     * message body, either for matching or for the resulting action.
+     */
+    boolean doFiltersNeedMessageBody(in nsMsgFilterTypeType filterType);
 };


diff --git a/mailnews/search/src/nsMsgFilterList.cpp b/mailnews/search/src/nsMsgFilterList.cpp
index 6131887b9bb..799bd6ef9b3 100644
--- a/mailnews/search/src/nsMsgFilterList.cpp
+++ b/mailnews/search/src/nsMsgFilterList.cpp
@@ -1199,4 +1199,26 @@ NS_IMETHODIMP nsMsgFilterList::LogFilterMessage(const nsAString& message,
                "failed to write out end log tag");
   return NS_OK;
 }
+
+NS_IMETHODIMP nsMsgFilterList::DoFiltersNeedMessageBody(
+    nsMsgFilterTypeType filterType, bool* needsBody) {
+  NS_ENSURE_ARG_POINTER(needsBody);
+
+  *needsBody = false;
+  for (auto filter : m_filters) {
+    nsMsgFilterTypeType t;
+    nsresult rv = filter->GetFilterType(&t);
+    NS_ENSURE_SUCCESS(rv, rv);
+    if (!(t & filterType)) {
+      continue;
+    }
+    rv = filter->GetNeedsMessageBody(needsBody);
+    NS_ENSURE_SUCCESS(rv, rv);
+    if (*needsBody) {
+      return NS_OK;
+    }
+  }
+  return NS_OK;
+}
+
